import Ajv from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function cleanInstancePath(instancePath: string): string {
  const withoutSlash = instancePath.replace(/^[/.]/, '');
  return withoutSlash.replace(/\//g, '.');
}

const AJV_OPTIONS = {
  strict: false,
  validateFormats: false,
  coerceTypes: false,
  useDefaults: false,
};

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv(AJV_OPTIONS);
  private readonly dynamicSchemaValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
    try {
      return this.ajv.compile(schema);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw new Error(`Failed to compile schema for tool "${toolName}": ${message}`, {cause: error});
    }
  }

  private getValidator(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
    if (tool.validator) {
      return tool.validator;
    }
    const schema = definition.inputSchema;
    if (typeof schema !== 'object' || schema === null) {
      return this.compileSchema(definition.name, schema);
    }
    let validator = this.dynamicSchemaValidators.get(schema);
    if (!validator) {
      validator = this.compileSchema(definition.name, schema);
      this.dynamicSchemaValidators.set(schema, validator);
    }
    return validator;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      validator = this.compileSchema(resolved.name, resolved.inputSchema);
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against the registered inputSchema; returns a rejection ToolResponse on schema failure and throws only for unknown tools (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = this.getValidator(tool, definition);
    if (!validator(input)) {
      const rejectionMessage = this.formatValidationErrors(definition.name, validator.errors);
      log.warn('tool', 'tool input validation failed', {name});
      return {result: rejectionMessage};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private formatValidationErrors(toolName: string, errors?: readonly unknown[] | null): string {
    if (!errors || errors.length === 0) {
      return `Invalid input for tool "${toolName}"`;
    }
    const descriptions: string[] = [];
    for (const err of errors) {
      if (!isRecord(err)) {
        continue;
      }
      descriptions.push(this.formatSingleValidationError(err));
    }
    if (descriptions.length === 0) {
      return `Invalid input for tool "${toolName}"`;
    }
    return `Invalid input for tool "${toolName}": ${descriptions.join('; ')}`;
  }

  private formatSingleValidationError(err: Record<string, unknown>): string {
    const rawPath =
      typeof err.instancePath === 'string' ? err.instancePath : typeof err.dataPath === 'string' ? err.dataPath : '';
    const params = isRecord(err.params) ? err.params : undefined;
    const missingProp = typeof params?.missingProperty === 'string' ? params.missingProperty : '';
    const fieldPath = rawPath ? cleanInstancePath(rawPath) : missingProp;

    if (err.keyword === 'required' && missingProp) {
      return `missing required property "${missingProp}"`;
    }
    if (err.keyword === 'type' && typeof params?.type === 'string') {
      const expectedType: string = params.type;
      return `property "${fieldPath}" must be of type ${expectedType}`;
    }
    if (err.keyword === 'enum' && Array.isArray(params?.allowedValues)) {
      return `property "${fieldPath}" must be one of allowed values`;
    }
    const fallbackMessage = typeof err.message === 'string' ? err.message : 'is invalid';
    return fieldPath ? `property "${fieldPath}" ${fallbackMessage}` : fallbackMessage;
  }
}

